import { ref, onMounted, onUnmounted } from 'vue';
import * as echarts from 'echarts';
import axios from 'axios';
import { API_CONFIG } from './config';
export default {
  __name: 'BigdataUser',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const genderChart = ref(null);
    const ageChart = ref(null);
    let genderChartInstance = null;
    let ageChartInstance = null;
    const renderGenderChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/gender-distribution`);
        const data = response.data;
        const total = data.male_count + data.female_count;
        genderChartInstance = echarts.init(genderChart.value);
        const option = {
          title: {
            text: `总人数: ${total}`,
            left: '5%',
            top: '5%',
            textStyle: {
              fontSize: 14,
              fontWeight: 'normal',
              color: '#666'
            }
          },
          tooltip: {
            trigger: 'item',
            formatter: params => {
              return `${params.name}: ${params.value}人 (${params.percent}%)`;
            }
          },
          series: [{
            name: '性别分布',
            type: 'pie',
            radius: '70%',
            center: ['50%', '50%'],
            avoidLabelOverlap: false,
            itemStyle: {
              borderColor: '#fff',
              borderWidth: 2
            },
            label: {
              show: true,
              formatter: '{b}: {d}%',
              position: 'outside'
            },
            emphasis: {
              label: {
                show: true,
                fontSize: '14',
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: true,
              length: 10,
              length2: 15
            },
            data: [{
              value: data.male_count,
              name: '男',
              itemStyle: {
                color: '#1890ff',
                shadowBlur: 10,
                shadowColor: 'rgba(0, 0, 0, 0.3)'
              }
            }, {
              value: data.female_count,
              name: '女',
              itemStyle: {
                color: '#f04864',
                shadowBlur: 10,
                shadowColor: 'rgba(0, 0, 0, 0.3)'
              }
            }]
          }]
        };
        genderChartInstance.setOption(option);
      } catch (error) {
        console.error('获取性别分布数据失败:', error);
      }
    };
    const renderAgeChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/age-distribution`);
        const data = response.data;
        ageChartInstance = echarts.init(ageChart.value);
        const option = {
          title: {
            text: '年龄分布',
            left: 'center',
            top: '5%',
            textStyle: {
              fontSize: 14,
              fontWeight: 'normal',
              color: '#666'
            }
          },
          tooltip: {
            trigger: 'axis',
            formatter: function (params) {
              const seriesName = params.seriesName;
              const dataIndex = params.dataIndex;
              if (data && data.male_counts && data.female_counts && dataIndex < data.male_counts.length && dataIndex < data.female_counts.length) {
                const maleCount = data.male_counts[dataIndex];
                const femaleCount = data.female_counts[dataIndex];
                const totalCount = maleCount + femaleCount;
                if (seriesName === '男') {
                  return `${params.name}<br/>男: ${maleCount}人<br/>女: ${femaleCount}人<br/>总数: ${totalCount}人`;
                } else if (seriesName === '女') {
                  return `${params.name}<br/>男: ${maleCount}人<br/>女: ${femaleCount}人<br/>总数: ${totalCount}人`;
                }
              }
              return `${params.name}<br/>数据获取错误`;
            }
          },
          xAxis: {
            type: 'category',
            data: data.age_groups,
            axisTick: {
              alignWithLabel: true
            }
          },
          yAxis: {
            type: 'value'
          },
          series: [{
            name: '男',
            type: 'bar',
            data: data.male_counts,
            itemStyle: {
              color: '#1890ff'
            },
            stack: 'total'
          }, {
            name: '女',
            type: 'bar',
            data: data.female_counts,
            itemStyle: {
              color: '#f04864'
            },
            stack: 'total'
          }]
        };
        ageChartInstance.setOption(option);
      } catch (error) {
        console.error('获取年龄分布数据失败:', error);
      }
    };
    const handleResize = () => {
      if (genderChartInstance) genderChartInstance.resize();
      if (ageChartInstance) ageChartInstance.resize();
    };
    onMounted(() => {
      renderGenderChart();
      renderAgeChart();
      window.addEventListener('resize', handleResize);
    });
    onUnmounted(() => {
      window.removeEventListener('resize', handleResize);
      if (genderChartInstance) {
        genderChartInstance.dispose();
        genderChartInstance = null;
      }
      if (ageChartInstance) {
        ageChartInstance.dispose();
        ageChartInstance = null;
      }
    });
    const __returned__ = {
      genderChart,
      ageChart,
      get genderChartInstance() {
        return genderChartInstance;
      },
      set genderChartInstance(v) {
        genderChartInstance = v;
      },
      get ageChartInstance() {
        return ageChartInstance;
      },
      set ageChartInstance(v) {
        ageChartInstance = v;
      },
      renderGenderChart,
      renderAgeChart,
      handleResize,
      ref,
      onMounted,
      onUnmounted,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      },
      get API_CONFIG() {
        return API_CONFIG;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
